CREATE COLUMN TABLE "TEST_AP"."OIBQ" ("AbsEntry" INTEGER CS_INT NOT NULL , "ItemCode" NVARCHAR(50) NOT NULL , "BinAbs" INTEGER CS_INT NOT NULL , "OnHandQty" DECIMAL(21,6) CS_FIXED, "WhsCode" NVARCHAR(8), "Freezed" NVARCHAR(1) DEFAULT 'N', "FreezeDoc" INTEGER CS_INT, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OIBQ_BUSINESS_K" ON "TEST_AP"."OIBQ" ( "ItemCode" ASC, "BinAbs" ASC );
CREATE INDEX "OIBQ_BIN_ABS" ON "TEST_AP"."OIBQ" ( "BinAbs" ASC )